def test_post_v2_money_management_transactions_id_example_parses() -> None:
    example = {
        "pathParams": {"id": "trxn_65NygiBHKcUPGUI8A5Q16NoTesLDSQ1IgNPigisRKq0GAq"},
        "requestBody": {"description": "Payout to John for design work"},
    }
    payload = {"action": "post_v2_money_management_transactions_id", "id": "example"}
    field_by_wire = {"description": "description", "metadata": "metadata"}
    if isinstance(example, dict):
        payload.update({field_by_wire[k]: v for k, v in example.items() if k in field_by_wire})
    sch.PostV2MoneyManagementTransactionsIdInput.model_validate(payload)


